def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_opponents = 0
    rich_alive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY:
                rich_alive += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / WATER_REQ
    low_supply = units < 1.6
    high_supply = units >= 1.85

    if hp <= 2 or no_water >= 2:
        bid = max(62.0, highest_prev + 2.0)
    elif hp <= 4 or no_water >= 1:
        if low_supply:
            bid = max(49.0, highest_prev + 1.5)
        else:
            bid = max(41.0, avg_prev + 1.0)
    else:
        if high_supply:
            bid = 19.0
        elif low_supply:
            bid = max(28.0, min(44.0, avg_prev + 0.5))
        else:
            bid = max(23.0, min(36.0, avg_prev))

    if highest_prev >= 85.0 and hp > 4 and no_water == 0:
        bid = min(bid, 24.0)

    if rich_alive >= 2 and low_supply and hp > 4 and no_water == 0:
        bid += 4.0

    if urgent_opponents >= 2 and hp > 4 and no_water == 0 and low_supply:
        bid = min(bid, 26.0)

    if day >= 8:
        bid += 4.0
    if day >= 9 and (hp <= 4 or no_water >= 1):
        bid += 8.0

    reserve_floor = 0.0
    if day < 9:
        reserve_floor = DAILY_SALARY * 0.35
    max_affordable = max(0.0, budget - reserve_floor)
    if hp <= 3 or no_water >= 1:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    supply = day_context['supply']

    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace')]
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 40.0

    if supply < WATER_REQ * 2:
        bid = avg_prev + 5.0
    else:
        bid = avg_prev * 0.9

    if my_status['hp'] < 3:
        bid = max(bid, DAILY_SALARY * 0.6)

    return float(min(my_status['budget'], max(0.0, bid)))
